import { db } from '../firebase/config';
import { collection, setDoc, getDoc, getDocs, updateDoc, deleteDoc, doc, query, where } from 'firebase/firestore';
import type { Availability } from '../types/Availability';
import { DAY_NAMES } from "../pages/student/student-utils";

// Collection: availability. Document IDs are generated by Firestore and copied into availID.
const COLLECTION = 'availability';

export function slotKeyToAvailability(
  slot: string,
  volUID: string
): Omit<Availability, "availID"> {
  const [weekdayStr, hourStr] = slot.split(":");
  const weekday = Number(weekdayStr);
  const hour = Number(hourStr);

  return {
    volUID,
    dayOfWeek: DAY_NAMES[weekday],
    availTimeSlot: hour,
  };
}

// ~~~~~~~~~~ CREATE ~~~~~~~~~~

// Returns the new availID
export const createAvailability = async (data: Omit<Availability, 'availID'>): Promise<string> => {
  try {
    const ref = doc(collection(db, COLLECTION));
    await setDoc(ref, { ...data, availID: ref.id });
    return ref.id;
  } catch (error) {
    console.error('Error creating availability:', error);
    throw error;
  }
};

// ~~~~~~~~~~ READ ~~~~~~~~~~

// Get one availability slot by availID
export const getAvailability = async (availID: string): Promise<Availability | null> => {
  try {
    const snap = await getDoc(doc(db, COLLECTION, availID));
    return snap.exists() ? (snap.data() as Availability) : null;
  } catch (error) {
    console.error(`Error getting availability "${availID}":`, error);
    throw error;
  }
};

// Get all of a volunteer's slots (the time-slot grid in the session form)
export const getAvailabilityByVolunteer = async (volUID: string): Promise<Availability[]> => {
  try {
    const snap = await getDocs(query(collection(db, COLLECTION), where('volUID', '==', volUID)));
    return snap.docs.map(d => d.data() as Availability);
  } catch (error) {
    console.error(`Error getting availability for volunteer "${volUID}":`, error);
    throw error;
  }
};

// Get a volunteer's slots for one day of the week
export const getAvailabilityByVolunteerAndDay = async (volUID: string, dayOfWeek: string): Promise<Availability[]> => {
  try {
    const snap = await getDocs(
      query(collection(db, COLLECTION), where('volUID', '==', volUID), where('dayOfWeek', '==', dayOfWeek))
    );
    return snap.docs.map(d => d.data() as Availability);
  } catch (error) {
    console.error(`Error getting ${dayOfWeek} availability for volunteer "${volUID}":`, error);
    throw error;
  }
};

// ~~~~~~~~~~ UPDATE ~~~~~~~~~~

export const updateAvailability = async (availID: string, updates: Partial<Omit<Availability, 'availID'>>): Promise<void> => {
  try {
    await updateDoc(doc(db, COLLECTION, availID), { ...updates });
  } catch (error) {
    console.error(`Error updating availability "${availID}":`, error);
    throw error;
  }
};

// ~~~~~~~~~~ DELETE ~~~~~~~~~~

export const deleteAvailability = async (availID: string): Promise<void> => {
  try {
    await deleteDoc(doc(db, COLLECTION, availID));
  } catch (error) {
    console.error(`Error deleting availability "${availID}":`, error);
    throw error;
  }
};